INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (1, 'Feijoada Caseira', 'Uma receita tradicional, cozida devagar, com feijão preto e carnes defumadas. Perfeita para o almoço de domingo.', '/images/feijoada.png', 4.9, '1h30', 1);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 0, '500 g de feijão preto');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 1, '300 g de carne seca dessalgada');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 2, '2 linguiças calabresas');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 3, '200 g de costelinha de porco');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 4, '1 cebola picada');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 5, '4 dentes de alho');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (1, 6, '2 folhas de louro');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (1, 0, 'Deixe o feijão de molho por pelo menos 8 horas.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (1, 1, 'Cozinhe o feijão na pressão com o louro por 30 minutos.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (1, 2, 'Frite a carne seca, a costelinha e a linguiça em pedaços.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (1, 3, 'Refogue a cebola e o alho e junte as carnes ao feijão.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (1, 4, 'Cozinhe em fogo baixo por mais 30 minutos e sirva com arroz e couve.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (2, 'Strogonoff de Frango', 'Cremoso e fácil de fazer, é aquele prato que agrada toda a família.', '/images/strogonoff.png', 4.7, '40min', 1);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 0, '600 g de peito de frango em cubos');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 1, '1 cebola picada');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 2, '2 dentes de alho');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 3, '1 lata de creme de leite');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 4, '4 colheres de ketchup');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 5, '1 colher de mostarda');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (2, 6, '200 g de champignon');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (2, 0, 'Tempere o frango com sal e alho.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (2, 1, 'Doure o frango na manteiga com a cebola.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (2, 2, 'Acrescente o ketchup, a mostarda e o champignon.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (2, 3, 'Cozinhe por 10 minutos e desligue o fogo.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (2, 4, 'Misture o creme de leite e sirva com arroz e batata palha.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (3, 'Lasanha à Bolonhesa', 'Camadas de massa, molho de carne e queijo gratinado, como a vovó faz.', '/images/lasanha.png', 4.8, '1h20', 2);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (3, 0, '500 g de massa de lasanha');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (3, 1, '500 g de carne moída');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (3, 2, '700 ml de molho de tomate');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (3, 3, '400 g de presunto fatiado');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (3, 4, '400 g de queijo mussarela fatiado');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (3, 5, 'Molho branco a gosto');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (3, 0, 'Refogue a carne moída e junte o molho de tomate.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (3, 1, 'Cozinhe a massa conforme a embalagem.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (3, 2, 'Monte em camadas: molho, massa, presunto, queijo e molho branco.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (3, 3, 'Repita as camadas e finalize com queijo.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (3, 4, 'Asse a 200 °C por 30 minutos, até gratinar.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (4, 'Macarrão ao Alho e Óleo', 'Simples, rápido e cheio de sabor. Ótimo para quando o tempo está curto.', '/images/alho-e-oleo.png', 4.5, '20min', 2);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (4, 0, '300 g de espaguete');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (4, 1, '6 dentes de alho fatiados');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (4, 2, '1/2 xícara de azeite');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (4, 3, 'Pimenta calabresa a gosto');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (4, 4, 'Salsinha picada');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (4, 5, 'Sal a gosto');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (4, 0, 'Cozinhe o espaguete em água com sal até ficar al dente.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (4, 1, 'Aqueça o azeite e doure o alho em fogo baixo.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (4, 2, 'Junte a pimenta calabresa.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (4, 3, 'Misture o macarrão escorrido ao azeite.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (4, 4, 'Finalize com salsinha e sirva quente.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (5, 'Pudim de Leite', 'O clássico pudim cremoso, sem furinhos, com calda de caramelo dourada.', '/images/pudim.png', 4.9, '1h15', 3);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (5, 0, '1 lata de leite condensado');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (5, 1, '2 latas de leite (use a lata do leite condensado)');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (5, 2, '3 ovos');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (5, 3, '1 xícara de açúcar para a calda');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (5, 0, 'Derreta o açúcar em fogo baixo até virar caramelo.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (5, 1, 'Espalhe o caramelo na forma de pudim.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (5, 2, 'Bata no liquidificador o leite condensado, o leite e os ovos.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (5, 3, 'Despeje na forma e cubra com papel alumínio.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (5, 4, 'Asse em banho-maria a 180 °C por 50 minutos.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (5, 5, 'Espere esfriar e leve à geladeira por 4 horas antes de desenformar.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (6, 'Bolo de Cenoura', 'Fofinho, úmido e coberto com a clássica cobertura de chocolate.', '/images/bolo-de-cenoura.png', 4.8, '55min', 3);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 0, '3 cenouras médias picadas');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 1, '4 ovos');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 2, '1 xícara de óleo');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 3, '2 xícaras de açúcar');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 4, '2 xícaras de farinha de trigo');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 5, '1 colher (sopa) de fermento');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (6, 6, 'Cobertura: chocolate em pó, açúcar, manteiga e leite');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (6, 0, 'Bata no liquidificador a cenoura, os ovos e o óleo.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (6, 1, 'Misture com o açúcar e a farinha.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (6, 2, 'Acrescente o fermento e mexa delicadamente.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (6, 3, 'Asse em forma untada a 180 °C por 40 minutos.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (6, 4, 'Prepare a cobertura no fogo e despeje sobre o bolo.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (7, 'Caldo Verde', 'Sopa quentinha de batata com couve e linguiça, ideal para dias frios.', '/images/caldo-verde.png', 4.6, '45min', 4);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (7, 0, '5 batatas médias');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (7, 1, '1 cebola');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (7, 2, '3 dentes de alho');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (7, 3, '1 maço de couve fatiada fina');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (7, 4, '200 g de linguiça calabresa');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (7, 5, 'Azeite e sal a gosto');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (7, 0, 'Refogue a cebola e o alho no azeite.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (7, 1, 'Junte as batatas e cubra com água.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (7, 2, 'Cozinhe até as batatas ficarem macias e bata no liquidificador.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (7, 3, 'Volte ao fogo e acrescente a linguiça frita.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (7, 4, 'Adicione a couve, cozinhe por 5 minutos e sirva.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (8, 'Salada Tropical', 'Fresca e colorida, com folhas, manga e um toque de limão.', '/images/salada-tropical.png', 4.3, '15min', 5);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (8, 0, '1 maço de alface');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (8, 1, '1 manga madura em cubos');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (8, 2, '1 tomate picado');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (8, 3, '1/2 cebola roxa em fatias');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (8, 4, 'Suco de 1 limão');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (8, 5, 'Azeite e sal a gosto');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (8, 0, 'Lave e rasgue as folhas de alface.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (8, 1, 'Misture o tomate, a manga e a cebola roxa.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (8, 2, 'Tempere com limão, azeite e sal.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (8, 3, 'Sirva em seguida, bem gelada.');
INSERT INTO receitas (id, titulo, descricao, imagem, nota, tempo, categoria_id) VALUES (9, 'Pão de Queijo', 'Crocante por fora, macio por dentro. Impossível comer só um.', '/images/pao-de-queijo.png', 4.9, '50min', 6);
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (9, 0, '500 g de polvilho azedo');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (9, 1, '1 xícara de leite');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (9, 2, '1/2 xícara de óleo');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (9, 3, '2 ovos');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (9, 4, '200 g de queijo minas curado ralado');
INSERT INTO receita_ingredientes (receita_id, posicao, ingrediente) VALUES (9, 5, '1 colher (chá) de sal');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (9, 0, 'Ferva o leite com o óleo e o sal.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (9, 1, 'Escalde o polvilho com a mistura e deixe amornar.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (9, 2, 'Junte os ovos e o queijo e amasse até dar liga.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (9, 3, 'Faça bolinhas e coloque em uma assadeira.');
INSERT INTO receita_preparo (receita_id, posicao, passo) VALUES (9, 4, 'Asse a 200 °C por 25 minutos, até dourar.');
